`default_nettype none
// Six registered sampling stages, four parity banks per plane. Each bank has
// one synchronous read port, with no framebuffer and no fourfold ROM copies.
module visual_background(input wire clk,input wire [11:0] x,y,
 output wire [23:0] sharp_rgb,frost_rgb);
 visual_texture_plane #(.SHIFT(3),.BW(121),.BH(68),
  .FILE0("assets/bg_fine_0_packed18.hex"),.FILE1("assets/bg_fine_1_packed18.hex"),
  .FILE2("assets/bg_fine_2_packed18.hex"),.FILE3("assets/bg_fine_3_packed18.hex")) sharp(clk,x,y,sharp_rgb);
 visual_texture_plane #(.SHIFT(6),.BW(16),.BH(9),
  .FILE0("assets/bg_frost_0_packed18.hex"),.FILE1("assets/bg_frost_1_packed18.hex"),
  .FILE2("assets/bg_frost_2_packed18.hex"),.FILE3("assets/bg_frost_3_packed18.hex")) frost(clk,x,y,frost_rgb);
endmodule
/* verilator lint_off DECLFILENAME */
module visual_texture_plane #(parameter SHIFT=3,BW=121,BH=68,
 parameter FILE0="",FILE1="",FILE2="",FILE3="")(
 input wire clk,input wire [11:0] x,y,output reg [23:0] rgb);
 localparam WORDS=BW*BH;
 wire [23:0] q0,q1,q2,q3;reg [1:0] corner;
 localparam WEIGHT_W=2*SHIFT+1,ACC_W=2*SHIFT+9;
 reg [WEIGHT_W-1:0] wa,wb,wc,wd;
 reg [WEIGHT_W-1:0] wa_addr,wb_addr,wc_addr,wd_addr,wa_addr2,wb_addr2,wc_addr2,wd_addr2;
 reg [1:0] corner_addr,corner_addr2;
 wire [11:0] cx=x<1920?x:12'd1919,cy=y<1080?y:12'd1079;
 wire [8:0] gx=9'(cx>>SHIFT);wire [7:0] gy=8'(cy>>SHIFT);
 wire [31:0] address00,address01,address10,address11;
 visual_texture_address #(.BW(BW),.WORDS(WORDS)) addresses(
  clk,gx,gy,address00,address01,address10,address11);
 visual_texture_rom24_packed #(.WORDS(WORDS),.FILE(FILE0),.REGISTER_ADDR(2)) rom0(clk,address00,q0);
 visual_texture_rom24_packed #(.WORDS(WORDS),.FILE(FILE1),.REGISTER_ADDR(2)) rom1(clk,address01,q1);
 visual_texture_rom24_packed #(.WORDS(WORDS),.FILE(FILE2),.REGISTER_ADDR(2)) rom2(clk,address10,q2);
 visual_texture_rom24_packed #(.WORDS(WORDS),.FILE(FILE3),.REGISTER_ADDR(2)) rom3(clk,address11,q3);
 function automatic [23:0] select_q(input [1:0] index,input [23:0] v0,v1,v2,v3);
  begin case(index)0:select_q=v0;1:select_q=v1;2:select_q=v2;default:select_q=v3;endcase end
 endfunction
 // Bank k always feeds the same multiplier; the weight follows the corner
 // (bank k holds bilinear role k^corner). Same four products, same sum, but
 // no texel multiplexer between the ROM outputs and the multipliers.
 function automatic [WEIGHT_W-1:0] select_w(input [1:0] role,input [WEIGHT_W-1:0] w0,w1,w2,w3);
  begin case(role)0:select_w=w0;1:select_w=w1;2:select_w=w2;default:select_w=w3;endcase end
 endfunction
 reg [ACC_W-1:0] pa[0:2],pb[0:2],pc[0:2],pd[0:2];
 reg [23:0] sample_a,sample_b,sample_c,sample_d;
 reg [WEIGHT_W-1:0] weight_a,weight_b,weight_c,weight_d;
 integer channel;
 always @(posedge clk)begin
  corner<={gy[0],gx[0]};
  wa<=WEIGHT_W'((1<<SHIFT)-{1'b0,cx[SHIFT-1:0]})*WEIGHT_W'((1<<SHIFT)-{1'b0,cy[SHIFT-1:0]});
  wb<=WEIGHT_W'(cx[SHIFT-1:0])*WEIGHT_W'((1<<SHIFT)-{1'b0,cy[SHIFT-1:0]});
  wc<=WEIGHT_W'((1<<SHIFT)-{1'b0,cx[SHIFT-1:0]})*WEIGHT_W'(cy[SHIFT-1:0]);
  wd<=WEIGHT_W'(cx[SHIFT-1:0])*WEIGHT_W'(cy[SHIFT-1:0]);
  corner_addr<=corner;wa_addr<=wa;wb_addr<=wb;wc_addr<=wc;wd_addr<=wd;
  corner_addr2<=corner_addr;wa_addr2<=wa_addr;wb_addr2<=wb_addr;wc_addr2<=wc_addr;wd_addr2<=wd_addr;
  sample_a<=q0;sample_b<=q1;sample_c<=q2;sample_d<=q3;
  weight_a<=select_w(corner_addr2,wa_addr2,wb_addr2,wc_addr2,wd_addr2);
  weight_b<=select_w(corner_addr2^2'd1,wa_addr2,wb_addr2,wc_addr2,wd_addr2);
  weight_c<=select_w(corner_addr2^2'd2,wa_addr2,wb_addr2,wc_addr2,wd_addr2);
  weight_d<=select_w(corner_addr2^2'd3,wa_addr2,wb_addr2,wc_addr2,wd_addr2);
  for(channel=0;channel<3;channel=channel+1)begin
   pa[channel]<=ACC_W'(sample_a[channel*8+:8])*weight_a;pb[channel]<=ACC_W'(sample_b[channel*8+:8])*weight_b;
   pc[channel]<=ACC_W'(sample_c[channel*8+:8])*weight_c;pd[channel]<=ACC_W'(sample_d[channel*8+:8])*weight_d;
   rgb[channel*8+:8]<=8'(((pa[channel]+pb[channel])+(pc[channel]+pd[channel])+(1<<(SHIFT*2-1)))>>(SHIFT*2));
  end
 end
endmodule
// Two reads from one native 18-bit ROM reconstruct each exact 24-bit texel.
// No quantization, decompression state, extra sampling delay or image change.
module visual_texture_rom24_packed #(parameter WORDS=1,FILE="",parameter REGISTER_ADDR=0)(
 input wire clk,input wire [31:0] addr,output wire [23:0] rgb);
 localparam AW=$clog2(WORDS)>0?$clog2(WORDS):1;
 localparam PW=(WORDS*24+17)/18+1;
 localparam BLOCKS=(PW+1023)/1024;
 localparam SW=$clog2(BLOCKS)>0?$clog2(BLOCKS):1;
 localparam PLANE=FILE=="assets/bg_fine_0_packed18.hex"?0:FILE=="assets/bg_fine_1_packed18.hex"?1:FILE=="assets/bg_fine_2_packed18.hex"?2:FILE=="assets/bg_fine_3_packed18.hex"?3:FILE=="assets/bg_frost_0_packed18.hex"?4:FILE=="assets/bg_frost_1_packed18.hex"?5:FILE=="assets/bg_frost_2_packed18.hex"?6:FILE=="assets/bg_frost_3_packed18.hex"?7:-1;
 function automatic [18431:0] packed_init(input integer plane,block);
  begin case({8'(plane),8'(block)})
   16'h0000:packed_init=18432';
   16'h0001:packed_init=18432';
   16'h0002:packed_init=18432';
   16'h0003:packed_init=18432';
   16'h0004:packed_init=18432';
   16'h0005:packed_init=18432';
   16'h0006:packed_init=18432';
   16'h0007:packed_init=18432';
   16'h0008:packed_init=18432';
   16'h0009:packed_init=18432';
   16'h000a:packed_init=18432';
   16'h0100:packed_init=18432';
   16'h0101:packed_init=18432';
   16'h0102:packed_init=18432';
   16'h0103:packed_init=18432';
   16'h0104:packed_init=18432';
   16'h0105:packed_init=18432';
   16'h0106:packed_init=18432';
   16'h0107:packed_init=18432';
   16'h0108:packed_init=18432';
   16'h0109:packed_init=18432';
   16'h010a:packed_init=18432';
   16'h0200:packed_init=18432';
   16'h0201:packed_init=18432';
   16'h0202:packed_init=18432';
   16'h0203:packed_init=18432';
   16'h0204:packed_init=18432';
   16'h0205:packed_init=18432';
   16'h0206:packed_init=18432';
   16'h0207:packed_init=18432';
   16'h0208:packed_init=18432';
   16'h0209:packed_init=18432';
   16'h020a:packed_init=18432';
   16'h0300:packed_init=18432';
   16'h0301:packed_init=18432';
   16'h0302:packed_init=18432';
   16'h0303:packed_init=18432';
   16'h0304:packed_init=18432';
   16'h0305:packed_init=18432';
   16'h0306:packed_init=18432';
   16'h0307:packed_init=18432';
   16'h0308:packed_init=18432';
   16'h0309:packed_init=18432';
   16'h030a:packed_init=18432';
   16'h0400:packed_init=18432';
   16'h0500:packed_init=18432';
   16'h0600:packed_init=18432';
   16'h0700:packed_init=18432';
   default:packed_init=0;
  endcase end
 endfunction
 reg [AW-1:0] addr_q;
 always @(posedge clk)addr_q<=addr[AW-1:0];
 wire [AW-1:0] local_addr=REGISTER_ADDR!=0?addr_q:addr[AW-1:0];
 wire [AW+1:0] scaled={local_addr,2'b00};
 localparam DIV_SHIFT=AW+2,PRODUCT_W=AW+DIV_SHIFT+1;
 localparam [PRODUCT_W-1:0] DIV3_RECIP=((1<<DIV_SHIFT)+2)/3;
 reg [PRODUCT_W-1:0] address_product;reg [AW-1:0] address_delayed;
 always @(posedge clk)begin
  address_product<=PRODUCT_W'(local_addr)*DIV3_RECIP;address_delayed<=local_addr;
 end
 wire [AW-1:0] quotient=AW'(address_product>>DIV_SHIFT);
 wire [AW+1:0] word_addr=REGISTER_ADDR==2?addr[AW+3:2]:REGISTER_ADDR!=0?{2'b0,address_delayed}+{2'b0,quotient}:scaled/(AW+2)'(3);
 wire [AW+1:0] next_addr=word_addr+1'b1;
 wire [1:0] residue=REGISTER_ADDR==2?addr[1:0]:REGISTER_ADDR!=0?2'(address_delayed)-2'(quotient)-{quotient[0],1'b0}:local_addr%AW'(3);
 wire [17:0] block_low[0:BLOCKS-1],block_high[0:BLOCKS-1];
 reg [SW-1:0] low_sel,high_sel;reg [3:0] shift_q;
 always @(posedge clk)begin
  low_sel<=SW'(32'(word_addr)>>10);high_sel<=SW'(32'(next_addr)>>10);
  shift_q<=4'(residue)*4'd6;
 end
 genvar g;
 generate for(g=0;g<BLOCKS;g=g+1)begin:PACKED
  localparam [18431:0] INIT=packed_init(PLANE,g);
  DPX9B #(.READ_MODE0(1'b0),.READ_MODE1(1'b0),.BIT_WIDTH_0(18),.BIT_WIDTH_1(18),
   .INIT_RAM_00(INIT[0+:288]),
   .INIT_RAM_01(INIT[288+:288]),
   .INIT_RAM_02(INIT[576+:288]),
   .INIT_RAM_03(INIT[864+:288]),
   .INIT_RAM_04(INIT[1152+:288]),
   .INIT_RAM_05(INIT[1440+:288]),
   .INIT_RAM_06(INIT[1728+:288]),
   .INIT_RAM_07(INIT[2016+:288]),
   .INIT_RAM_08(INIT[2304+:288]),
   .INIT_RAM_09(INIT[2592+:288]),
   .INIT_RAM_0A(INIT[2880+:288]),
   .INIT_RAM_0B(INIT[3168+:288]),
   .INIT_RAM_0C(INIT[3456+:288]),
   .INIT_RAM_0D(INIT[3744+:288]),
   .INIT_RAM_0E(INIT[4032+:288]),
   .INIT_RAM_0F(INIT[4320+:288]),
   .INIT_RAM_10(INIT[4608+:288]),
   .INIT_RAM_11(INIT[4896+:288]),
   .INIT_RAM_12(INIT[5184+:288]),
   .INIT_RAM_13(INIT[5472+:288]),
   .INIT_RAM_14(INIT[5760+:288]),
   .INIT_RAM_15(INIT[6048+:288]),
   .INIT_RAM_16(INIT[6336+:288]),
   .INIT_RAM_17(INIT[6624+:288]),
   .INIT_RAM_18(INIT[6912+:288]),
   .INIT_RAM_19(INIT[7200+:288]),
   .INIT_RAM_1A(INIT[7488+:288]),
   .INIT_RAM_1B(INIT[7776+:288]),
   .INIT_RAM_1C(INIT[8064+:288]),
   .INIT_RAM_1D(INIT[8352+:288]),
   .INIT_RAM_1E(INIT[8640+:288]),
   .INIT_RAM_1F(INIT[8928+:288]),
   .INIT_RAM_20(INIT[9216+:288]),
   .INIT_RAM_21(INIT[9504+:288]),
   .INIT_RAM_22(INIT[9792+:288]),
   .INIT_RAM_23(INIT[10080+:288]),
   .INIT_RAM_24(INIT[10368+:288]),
   .INIT_RAM_25(INIT[10656+:288]),
   .INIT_RAM_26(INIT[10944+:288]),
   .INIT_RAM_27(INIT[11232+:288]),
   .INIT_RAM_28(INIT[11520+:288]),
   .INIT_RAM_29(INIT[11808+:288]),
   .INIT_RAM_2A(INIT[12096+:288]),
   .INIT_RAM_2B(INIT[12384+:288]),
   .INIT_RAM_2C(INIT[12672+:288]),
   .INIT_RAM_2D(INIT[12960+:288]),
   .INIT_RAM_2E(INIT[13248+:288]),
   .INIT_RAM_2F(INIT[13536+:288]),
   .INIT_RAM_30(INIT[13824+:288]),
   .INIT_RAM_31(INIT[14112+:288]),
   .INIT_RAM_32(INIT[14400+:288]),
   .INIT_RAM_33(INIT[14688+:288]),
   .INIT_RAM_34(INIT[14976+:288]),
   .INIT_RAM_35(INIT[15264+:288]),
   .INIT_RAM_36(INIT[15552+:288]),
   .INIT_RAM_37(INIT[15840+:288]),
   .INIT_RAM_38(INIT[16128+:288]),
   .INIT_RAM_39(INIT[16416+:288]),
   .INIT_RAM_3A(INIT[16704+:288]),
   .INIT_RAM_3B(INIT[16992+:288]),
   .INIT_RAM_3C(INIT[17280+:288]),
   .INIT_RAM_3D(INIT[17568+:288]),
   .INIT_RAM_3E(INIT[17856+:288]),
   .INIT_RAM_3F(INIT[18144+:288])) rom(
   .DOA(block_low[g]),.DOB(block_high[g]),.DIA(18'd0),.DIB(18'd0),
   .BLKSELA(3'd0),.BLKSELB(3'd0),
   .ADA({10'(word_addr),4'd0}),.ADB({10'(next_addr),4'd0}),
   .WREA(1'b0),.WREB(1'b0),.CLKA(clk),.CLKB(clk),
   .CEA((32'(word_addr)>>10)==g),.CEB((32'(next_addr)>>10)==g),
   .OCEA(1'b1),.OCEB(1'b1),.RESETA(1'b0),.RESETB(1'b0));
 end endgenerate
 wire [17:0] low_q=block_low[low_sel],high_q=block_high[high_sel];
 wire [35:0] selected={high_q,low_q}>>shift_q;
 assign rgb=selected[23:0];
endmodule
